    private final Runnable ticker=new Runnable(){public void run(){
        try {
            Session done=timer.refresh(); LocalDate now=LocalDate.now();
            if(!today.equals(now)){today=now;store.ensureToday();DailyArchive.schedule(MainActivity.this);render();}
            TimerEngine.State s=timer.engine().snapshot();String id=s.sessionId;
            if(done!=null){completedId=done.id;DailyArchive.schedule(MainActivity.this);if(tab==0)render();}
            else if(!Objects.equals(renderedSession,id)||renderedPaused!=s.paused){if(tab==0&&page.isEmpty())render();}
            if(System.currentTimeMillis()-lastSyncRequest>30000){lastSyncRequest=System.currentTimeMillis();SyncEngine.request(MainActivity.this);}
            if(observedSyncVersion!=SyncEngine.appliedVersion&&page.isEmpty()&&activeDialog==null){observedSyncVersion=SyncEngine.appliedVersion;render();}
            updateTimer();if(backupStatus!=null)backupStatus.setText(DailyArchive.get(MainActivity.this).getBackupStatus());
        }catch(RuntimeException e){if(status!=null)status.setText("记录暂时无法读取，请重试");}
        handler.postDelayed(this,1000);
    }};

    @Override public void onCreate(Bundle saved){super.onCreate(saved);exportHideTasks=prefs().getBoolean("png-hide-task-details",false);timer=TimerCoordinator.get(this);store=timer.store();
        if(saved!=null){tab=saved.getInt("tab");page=saved.getString("page","");minutes=saved.getInt("minutes",25);selectedTaskId=saved.getString("task");editId=saved.getString("editId");completedId=saved.getString("completedId");detailDay=date(saved.getString("detail"));rangeStart=date(saved.getString("rangeStart"));rangeEnd=date(saved.getString("rangeEnd"));rangeMode=saved.getString("rangeMode","day");exportFormat=saved.getString("format","MARKDOWN");exportHideTasks=saved.getBoolean("hideTasks",exportHideTasks);exportJobId=saved.getString("job");pendingFile=saved.getString("pendingFile");pendingMime=saved.getString("pendingMime");pendingName=saved.getString("pendingName");copyJobId=saved.getString("copyJob");copyDestination=saved.getString("copyDestination");copyDeliveredId=saved.getString("copyDelivered");copySourceJobId=saved.getString("copySourceJob");galleryCopy=saved.getBoolean("galleryCopy");draftName=saved.getString("draftName");draftProgress=saved.getInt("draftProgress");draftRank=saved.getInt("draftRank",-1);reorderIds=saved.getStringArrayList("order");reordered=saved.getBoolean("reordered");restoreDialog=saved.getBundle("dialog");}
        getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(0xffF6F8F5);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        root=column();root.setBackgroundColor(android.graphics.Color.TRANSPARENT);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets a=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());root.setPadding(a.left,a.top,a.right,a.bottom);}else root.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});FrameLayout scene=new FrameLayout(this);scene.setBackgroundColor(PAPER);pageBackdrop=new ImageView(this);pageBackdrop.setScaleType(ImageView.ScaleType.CENTER_CROP);pageBackdrop.setTag("screen-backdrop");pageBackdrop.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);pageBackdrop.setAlpha(.88f);scene.addView(pageBackdrop,new FrameLayout.LayoutParams(-1,-1));scene.addView(root,new FrameLayout.LayoutParams(-1,-1));setContentView(scene);root.requestApplyInsets();
        try{store.ensureToday();DailyArchive.schedule(this);}catch(RuntimeException e){toast("记录初始化失败，数据未被删除");}render();
        if(restoreDialog!=null)root.post(()->{Bundle d=restoreDialog;restoreDialog=null;if(d==null)return;switch(d.getString("kind","")){case "progress":progressDialog(d.getString("task"),d.getInt("value"));break;case "manual":manualDialog(d);break;case "settlement":settlementDialog(date(d.getString("task")),d.getInt("value",-1));break;default:break;}});
    }
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
    @Override protected void onResume(){super.onResume();SyncEngine.request(this);try{timer.restoreFromForeground();store.ensureToday();DailyArchive.schedule(this);if(tab==0&&completedId==null&&!timer.engine().isActive()){List<Session> all=store.getSessions();if(!all.isEmpty()){Session s=all.get(0);String ack=prefs().getString("ack","");if(!s.id.equals(ack)&&"expired".equals(s.reason))completedId=s.id;}}}catch(RuntimeException e){toast("计时恢复暂时失败，请稍后重试");}render();handler.removeCallbacks(ticker);handler.post(ticker);if(exportJobId!=null)ExportWorker.get(this).observe(exportJobId,this::onExportChanged);if(copyJobId!=null){ExportWorker.Job copy=ExportWorker.get(this).observe(copyJobId,this::onCopyChanged);if(copy==null&&!copyJobId.equals(copyDeliveredId)){copyDeliveredId=copyJobId;new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("上次保存结果未确认").setMessage("应用在保存过程中被系统关闭，保存结果未确认。请检查相册或所选位置后重新保存。").setPositiveButton("知道了",null).show();}}}
    @Override protected void onPause(){handler.removeCallbacks(ticker);if(exportJobId!=null)ExportWorker.get(this).detach(exportJobId);if(copyJobId!=null)ExportWorker.get(this).detach(copyJobId);super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(manualChildDialog!=null)manualChildDialog.dismiss();if(activeDialog!=null)activeDialog.dismiss();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle s){captureDraft();s.putInt("tab",tab);s.putString("page",page);s.putInt("minutes",minutes);s.putString("task",selectedTaskId);s.putString("editId",editId);s.putString("completedId",completedId);s.putString("detail",detailDay.toString());s.putString("rangeStart",rangeStart.toString());s.putString("rangeEnd",rangeEnd.toString());s.putString("rangeMode",rangeMode);s.putString("format",exportFormat);s.putBoolean("hideTasks",exportHideTasks);s.putString("job",exportJobId);s.putString("pendingFile",pendingFile);s.putString("pendingMime",pendingMime);s.putString("pendingName",pendingName);s.putString("copyJob",copyJobId);s.putString("copyDestination",copyDestination);s.putString("copyDelivered",copyDeliveredId);s.putString("copySourceJob",copySourceJobId);s.putBoolean("galleryCopy",galleryCopy);s.putString("draftName",draftName);s.putInt("draftProgress",draftProgress);s.putInt("draftRank",draftRank);s.putStringArrayList("order",reorderIds);s.putBoolean("reordered",reordered);if(activeDialog!=null&&activeDialog.isShowing()&&dialogKind!=null){Bundle d=new Bundle();d.putString("kind",dialogKind);d.putString("task",dialogTask);d.putInt("value",dialogValue);if("manual".equals(dialogKind))saveManualDraft(d);s.putBundle("dialog",d);}super.onSaveInstanceState(s);}
    private android.content.SharedPreferences prefs(){return getSharedPreferences("shiben-v2-ui",MODE_PRIVATE);}
    private LocalDate date(String s){try{return LocalDate.parse(s);}catch(Exception e){return LocalDate.now();}}
    private void render(){if(root==null)return;captureDraft();root.removeAllViews();clock=null;elapsed=null;status=null;ring=null;editorName=null;editorProgress=null;editorRank=null;exportStatus=null;exportProgress=null;saveStatus=null;backupStatus=null;attentionTotal=null;attentionBreakdown=null;detailSummary=null;detailTotal=null;detailTaskTimes.clear();lastAttentionState=null;
        int nextBackdrop=tab==0?R.drawable.focus_backdrop:tab==1?R.drawable.tasks_backdrop:R.drawable.today_backdrop;if(backdropResource!=nextBackdrop){pageBackdrop.setImageResource(nextBackdrop);backdropResource=nextBackdrop;}content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        body=column();body.setPadding(dp(this,22),dp(this,16),dp(this,22),dp(this,20));
        if(tab==0&&page.isEmpty()){scroll=null;content.addView(body,new FrameLayout.LayoutParams(-1,-1));renderFocus();}
        else{scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));switch(page){case "edit":renderEditor();break;case "reorder":renderReorder();break;case "more":renderMore();break;case "settings":renderSettings();break;case "backup":renderBackup();break;case "weights":renderWeights();break;case "history":renderHistory();break;case "detail":renderDetail();break;case "export":renderExport();break;case "preview":renderPreview();break;default:if(tab==1)renderTasks();else renderToday();}}
        polishPage();buildTabs();TimerEngine.State s=timer.engine().snapshot();renderedSession=s.sessionId;renderedPaused=s.paused;updateTimer();
    }
    private void buildTabs(){LinearLayout tabs=row();tabs.setBackground(shape(0xF8FFFFFF,0x55DDE4E1,22,this));tabs.setPadding(dp(this,10),dp(this,7),dp(this,10),dp(this,6));String[] names={"专注","任务","今日"},icons={"focus","tasks","today"};for(int i=0;i<3;i++){final int t=i;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.setMinimumHeight(dp(this,58));Icon icon=new Icon(this,icons[i],i==tab?TEAL:MUTED);cell.addView(icon,new LinearLayout.LayoutParams(dp(this,25),dp(this,25)));TextView text=label(names[i],13,i==tab?TEAL:MUTED,false);text.setGravity(Gravity.CENTER);cell.addView(text);cell.setContentDescription(names[i]+(i==tab?"，已选中":""));cell.setFocusable(true);cell.setOnClickListener(v->leaveEditor(()->{tab=t;page="";clearDraft();render();}));tabs.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}root.addView(tabs,new LinearLayout.LayoutParams(-1,-2));}
    private LinearLayout glassPanel(){LinearLayout panel=column();panel.setPadding(dp(this,16),dp(this,18),dp(this,16),dp(this,18));panel.setBackground(shape(0xEFFFFFFF,0x44DDE5E1,18,this));return panel;}
    /** Presentation-only grouping; existing widgets, listeners and persisted state are retained. */
    private void polishPage(){if(!Arrays.asList("edit","backup","export","preview").contains(page)||body.getChildCount()<2)return;LinearLayout card=glassPanel();while(body.getChildCount()>1){View child=body.getChildAt(1);body.removeViewAt(1);card.addView(child);}gap(body,18);body.addView(card,new LinearLayout.LayoutParams(-1,-2));}
    /** Fixed-height home: decoration yields first on small screens and large font scales. */
    private boolean compactHome(){return getResources().getConfiguration().screenHeightDp<610||getResources().getConfiguration().fontScale>1.25f;}
    private void renderFocus(){
        TimerEngine.State s=timer.engine().snapshot();
        if(!timer.engine().isActive()&&completedId!=null){renderCompletion();return;}
        boolean active=timer.engine().isActive(),compact=compactHome();
        body.setPadding(dp(this,20),dp(this,compact?8:14),dp(this,20),dp(this,compact?8:14));
        LinearLayout titleRow=row();titleRow.setGravity(Gravity.CENTER_VERTICAL);
        LinearLayout titleStack=column();TextView heading=label(active?(s.paused?"已暂停":"专注中"):"时本",25,INK,true);
        titleStack.addView(heading);if(!compact){gap(titleStack,5);titleStack.addView(label("这是一场注意力的投资！",12,INK,false));}
        titleRow.addView(titleStack,new LinearLayout.LayoutParams(0,-2,1));

        body.addView(titleRow,new LinearLayout.LayoutParams(-1,-2));

        if(active){
            gap(body,8);TextView task=label(s.taskTitle,16,MUTED,false);task.setGravity(Gravity.CENTER);task.setMaxLines(1);task.setEllipsize(TextUtils.TruncateAt.END);task.setAutoSizeTextTypeUniformWithConfiguration(10,16,1,2);body.addView(task,new LinearLayout.LayoutParams(-1,dp(this,getResources().getConfiguration().fontScale>1.75f?32:28)));
            ring=new UiKit.HomeRing(this);body.addView(ring,new LinearLayout.LayoutParams(-1,0,1));
            elapsed=label("",14,MUTED,false);elapsed.setGravity(Gravity.CENTER);elapsed.setMaxLines(1);elapsed.setHorizontallyScrolling(false);elapsed.setAutoSizeTextTypeUniformWithConfiguration(10,14,1,2);body.addView(elapsed,new LinearLayout.LayoutParams(-1,dp(this,30)));gap(body,8);
            body.addView(homeButton(s.paused?"继续专注":"暂停",true,()->run(()->{if(timer.engine().isPaused())timer.resume();else timer.pause();render();})),new LinearLayout.LayoutParams(-1,dp(this,54)));gap(body,8);
            body.addView(homeButton("结束",false,this::finishDialog),new LinearLayout.LayoutParams(-1,dp(this,getResources().getConfiguration().fontScale>1.75f?54:48)));
        }else{
            UiKit.HomeRing ready=new UiKit.HomeRing(this);ready.set(1,TimerService.format(minutes*60000L),"专注，遇见更好的自己",false);ready.setContentDescription("准备专注，时长 "+minutes+" 分钟，尚未开始");body.addView(ready,new LinearLayout.LayoutParams(-1,0,1));
            LinearLayout controls=glassPanel();controls.setPadding(dp(this,10),dp(this,10),dp(this,10),dp(this,10));body.addView(controls,new LinearLayout.LayoutParams(-1,-2));
            List<LedgerStore.Task> tasks=store.getTasks(today);LedgerStore.Task selected=null;for(LedgerStore.Task t:tasks)if(t.id.equals(selectedTaskId))selected=t;if(selected==null&&!tasks.isEmpty()){selected=tasks.get(0);selectedTaskId=selected.id;}
            controls.addView(homeSelector("任务",selected==null?"暂无任务":selected.title,"book",this::chooseTask),new LinearLayout.LayoutParams(-1,dp(this,54)));gap(controls,6);
            controls.addView(homeSelector("时长",minutes+" 分钟","history",this::chooseMinutes),new LinearLayout.LayoutParams(-1,dp(this,54)));gap(controls,14);
            if(selected==null){TextView hint=label("先添加一个任务",14,INK,false);hint.setGravity(Gravity.CENTER);hint.setMaxLines(1);hint.setHorizontallyScrolling(false);hint.setAutoSizeTextTypeUniformWithConfiguration(10,14,1,2);controls.addView(hint,new LinearLayout.LayoutParams(-1,dp(this,24)));gap(controls,4);controls.addView(homeButton("添加任务",true,()->{tab=1;openEditor(null);}),new LinearLayout.LayoutParams(-1,dp(this,54)));}
            else controls.addView(homeButton("开始专注",true,()->run(()->{if(timer.engine().isActive())return;LedgerStore.Task t=store.getTask(selectedTaskId);if(t==null||t.archived){render();return;}ackCompletion();timer.start(t,minutes);render();})),new LinearLayout.LayoutParams(-1,dp(this,54)));
        }

    }
    private Button homeButton(String text,boolean filled,Runnable action){Button b=button(text,filled,action);b.setBackground(shape(filled?0xff08696E:0xEDFFFFFF,filled?0:0xff93B0AE,20,this));b.setTextSize(18);b.setMaxLines(1);b.setHorizontallyScrolling(false);b.setAutoSizeTextTypeUniformWithConfiguration(12,18,1,2);b.setElevation(dp(this,filled?2:0));return b;}
    private View homeSelector(String name,String value,String icon,Runnable action){LinearLayout card=row();card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(this,14),dp(this,6),dp(this,10),dp(this,6));card.setBackground(shape(0xEDFFFFFF,0x55DDE3E0,16,this));card.addView(new Icon(this,icon,INK),new LinearLayout.LayoutParams(dp(this,24),dp(this,24)));TextView label=label(name,16,INK,false);label.setMaxLines(1);label.setHorizontallyScrolling(false);label.setAutoSizeTextTypeUniformWithConfiguration(10,16,1,2);LinearLayout.LayoutParams key=new LinearLayout.LayoutParams(dp(this,56),-1);key.setMargins(dp(this,10),0,0,0);label.setGravity(Gravity.CENTER_VERTICAL);card.addView(label,key);LinearLayout box=row();box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(this,12),0,dp(this,8),0);box.setBackground(shape(0xAFFFFFFF,0xffE2E6E4,9,this));TextView selected=label(value,16,INK,false);selected.setMaxLines(1);selected.setHorizontallyScrolling(false);selected.setEllipsize(TextUtils.TruncateAt.END);selected.setGravity(Gravity.CENTER_VERTICAL);selected.setAutoSizeTextTypeUniformWithConfiguration(12,16,1,2);box.addView(selected,new LinearLayout.LayoutParams(0,-1,1));box.addView(new Icon(this,"down",MUTED),new LinearLayout.LayoutParams(dp(this,18),dp(this,18)));card.addView(box,new LinearLayout.LayoutParams(0,-1,1));card.setContentDescription(name+"，"+value);card.setFocusable(true);card.setOnClickListener(v->action.run());return card;}
    private void updateTimer(){if(timer==null)return;if(timer.engine().isActive()){TimerEngine.State s=timer.engine().snapshot();long remain=timer.remainingMs();if(ring!=null&&tab==0)ring.set(s.plannedMs==0?0:(double)remain/s.plannedMs,TimerService.format(remain),"",s.paused);if(elapsed!=null)elapsed.setText("已专注 "+shortDuration(timer.actualMs()));}updateAttentionTime();}
    /** Replace text only: a ticking timer must not rebuild lists, steal scroll, or reset a dialog. */
    private void updateAttentionTime(){
        if(attentionTotal==null&&(detailSummary==null||!detailDay.equals(LocalDate.now())))return;
        TimerEngine.State state=timer.engine().snapshot();String nextState=state.sessionId+":"+state.paused;
        boolean running=state.sessionId!=null&&!state.paused;
        if(!running&&Objects.equals(lastAttentionState,nextState))return;lastAttentionState=nextState;
        if(attentionTotal!=null){LedgerStore.DaySnapshot d=timer.snapshotForDay(today);attentionTotal.setText(attentionDuration(d.totalActualMs));attentionBreakdown.setText("专注计时 "+attentionDuration(Math.max(0,d.totalActualMs-d.totalManualMs))+" · 手动补记 "+attentionDuration(d.totalManualMs));}
        if(detailSummary!=null&&detailDay.equals(LocalDate.now())){LedgerStore.DaySnapshot d=timer.snapshotForDay(detailDay);detailSummary.setText(d.items.size()+" 个任务 · 投资注意力 "+shortDuration(d.totalActualMs));detailTotal.setText("实际注意力合计  "+shortDuration(d.totalActualMs));for(LedgerStore.DayTask task:d.items){TextView text=detailTaskTimes.get(task.taskId);if(text!=null)text.setText(detailTaskCaption(task));}}
    }
    private String attentionDuration(long ms){long seconds=Math.max(0,ms)/1000,minutes=seconds/60;return (minutes>=60?minutes/60+"小时":"")+minutes%60+"分"+seconds%60+"秒";}
    private String detailTaskCaption(LedgerStore.DayTask task){return (task.rank<0?"优先级未知":"优先级 "+task.rank)+" · 权重 "+percent(task.weight*100)+" · 注意力 "+shortDuration(task.actualMs);}
    private void renderCompletion(){Session s=store.getSession(completedId);if(s==null){completedId=null;renderFocus();return;}TextView h=label("本次专注完成",25,INK,true);h.setGravity(Gravity.CENTER);body.addView(h);FrameLayout center=new FrameLayout(this);LinearLayout stack=column();stack.setGravity(Gravity.CENTER);Icon check=new Icon(this,"check",TEAL);stack.addView(check,new LinearLayout.LayoutParams(dp(this,74),dp(this,74)));TextView duration=label(TimerService.format(s.actualMs),65,INK,false);duration.setGravity(Gravity.CENTER);stack.addView(duration);TextView title=label(s.taskTitle,18,MUTED,false);title.setGravity(Gravity.CENTER);stack.addView(title);center.addView(stack,new FrameLayout.LayoutParams(-1,-1));body.addView(center,new LinearLayout.LayoutParams(-1,0,1));notice(body,"任务进度需手动更新");gap(body,16);body.addView(button("调整任务进度",true,()->{String id=s.taskId;ackCompletion();tab=1;render();LedgerStore.Task task=store.getTask(id);if(task!=null&&!task.archived)progressDialog(id,-1);else toast("任务已移除，专注记录仍保留");}),new LinearLayout.LayoutParams(-1,dp(this,56)));gap(body,10);body.addView(button("返回专注",false,()->{ackCompletion();render();}),new LinearLayout.LayoutParams(-1,dp(this,52)));}
    private void ackCompletion(){if(completedId!=null)prefs().edit().putString("ack",completedId).apply();completedId=null;}
    private LinearLayout selector(String label,String value,Runnable click){LinearLayout r=row();r.setGravity(Gravity.CENTER_VERTICAL);TextView key=label(label,18,INK,false);r.addView(key,new LinearLayout.LayoutParams(dp(this,66),-1));key.setGravity(Gravity.CENTER_VERTICAL);LinearLayout box=row();box.setPadding(dp(this,15),0,dp(this,10),0);box.setGravity(Gravity.CENTER_VERTICAL);box.setBackground(shape(PAPER,LINE,6,this));TextView text=label(value,18,INK,false);text.setSingleLine();text.setEllipsize(TextUtils.TruncateAt.END);text.setAutoSizeTextTypeUniformWithConfiguration(13,18,1,2);box.addView(text,new LinearLayout.LayoutParams(0,-1,1));text.setGravity(Gravity.CENTER_VERTICAL);box.addView(new Icon(this,"down",MUTED),new LinearLayout.LayoutParams(dp(this,22),dp(this,22)));box.setContentDescription(label+"，"+value);box.setFocusable(true);box.setOnClickListener(v->click.run());r.addView(box,new LinearLayout.LayoutParams(0,-1,1));return r;}
    private void chooseTask(){List<LedgerStore.Task> list=store.getTasks(today);if(list.isEmpty()){tab=1;openEditor(null);return;}String[] names=new String[list.size()];int selected=0;LedgerStore.DaySnapshot day=store.getDaySnapshot(today);for(int i=0;i<list.size();i++){LedgerStore.Task t=list.get(i);names[i]=t.title+"   "+(progress(t.id,day)<0?"未知":progress(t.id,day)+"%");if(t.id.equals(selectedTaskId))selected=i;}final int[] pick={selected};new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("选择任务").setSingleChoiceItems(names,selected,(d,w)->pick[0]=w).setPositiveButton("确定",(d,w)->{selectedTaskId=list.get(pick[0]).id;render();}).setNegativeButton("取消",null).show();}
    private void chooseMinutes(){LinearLayout box=column();box.setPadding(dp(this,24),dp(this,8),dp(this,24),dp(this,8));NumberPicker picker=new NumberPicker(this);picker.setMinValue(3);picker.setMaxValue(288);picker.setValue(minutes/5);picker.setFormatter(v->(v*5)+" 分钟");picker.setWrapSelectorWheel(false);box.addView(picker);TextView hint=label("最少 15 分钟，每次增加 5 分钟",13,MUTED,false);box.addView(hint);new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("专注时长").setView(box).setPositiveButton("确定",(d,w)->{picker.clearFocus();minutes=picker.getValue()*5;render();}).setNegativeButton("取消",null).show();}
    private void finishDialog(){new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("结束本次专注？").setMessage("已专注 "+shortDuration(timer.actualMs())+"\n结束后保留本次记录，任务进度不变。").setNegativeButton("继续专注",null).setPositiveButton("结束并保存",(d,w)->run(()->{timer.finish();DailyArchive.schedule(this);render();})).show();}

    private void renderTasks(){LinearLayout header=header("当天任务",false);header.addView(iconButton("plus","新增任务",()->openEditor(null)));header.addView(iconButton("sort","调整优先级",()->{reorderIds=new ArrayList<>();for(LedgerStore.Task t:store.getTasks(today))reorderIds.add(t.id);reordered=false;page="reorder";render();}));gap(body,6);body.addView(label("把大目标，拆解成今天的行动。",13,MUTED,false));gap(body,22);LedgerStore.DaySnapshot day=store.getDaySnapshot(today);List<LedgerStore.Task> tasks=store.getTasks(today);if(tasks.isEmpty()){empty("还没有任务","任务与项目使用同一列表",()->openEditor(null),"添加任务");return;}for(LedgerStore.Task t:tasks){View row=taskRow(t.title,progress(t.id,day),()->progressDialog(t.id,-1));row.setOnLongClickListener(v->{openEditor(t.id);return true;});row.setContentDescription(t.title+"，进度 "+(progress(t.id,day)<0?"未知":progress(t.id,day)+"%")+"，点击调整进度，长按编辑任务");body.addView(row);gap(body,10);}gap(body,18);TextView help=label("点击调整进度 · 长按编辑任务",12,MUTED,false);help.setGravity(Gravity.CENTER);help.setPadding(dp(this,8),dp(this,8),dp(this,8),dp(this,8));help.setBackground(shape(0xEFFFFFFF,0,10,this));body.addView(help);gap(body,8);TextView daily=label("每日进度从 0% 开始，任务列表会保留",12,MUTED,false);daily.setGravity(Gravity.CENTER);daily.setPadding(dp(this,8),dp(this,8),dp(this,8),dp(this,8));daily.setBackground(shape(0xEFFFFFFF,0,10,this));body.addView(daily);}
    private int progress(String id,LedgerStore.DaySnapshot day){for(LedgerStore.DayTask t:day.items)if(t.taskId.equals(id))return t.progress;return 0;}
    private View taskRow(String title,int value,Runnable action){LinearLayout r=row();r.setGravity(Gravity.CENTER_VERTICAL);r.setMinimumHeight(dp(this,76));r.setPadding(dp(this,12),dp(this,12),dp(this,12),dp(this,12));r.setBackground(shape(0xEFFFFFFF,0x44DDE5E1,17,this));r.addView(new UiKit.TaskBadge(this,title),new LinearLayout.LayoutParams(dp(this,40),dp(this,40)));LinearLayout details=column();LinearLayout.LayoutParams detailParams=new LinearLayout.LayoutParams(0,-2,1);detailParams.setMargins(dp(this,12),0,dp(this,12),0);TextView name=label(title,16,INK,true);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);details.addView(name);gap(details,6);details.addView(new UiKit.Bar(this,value),new LinearLayout.LayoutParams(-1,dp(this,12)));r.addView(details,detailParams);TextView percent=label(value<0?"未知":value+"%",14,INK,false);percent.setGravity(Gravity.END);percent.setSingleLine(true);int percentWidth=dp(this,44f*Math.max(1f,getResources().getConfiguration().fontScale));r.addView(percent,new LinearLayout.LayoutParams(percentWidth,-2));if(action!=null){r.setFocusable(true);r.setOnClickListener(v->action.run());}return r;}
    private void progressDialog(String id,int restored){LedgerStore.Task task=store.getTask(id);if(task==null||task.archived)return;int old=progress(id,store.getDaySnapshot(today));dialogKind="progress";dialogTask=id;dialogValue=restored>=0?restored:Math.max(0,old);LinearLayout box=column();box.setPadding(dp(this,24),dp(this,12),dp(this,24),dp(this,12));TextView title=label(task.title,19,INK,false);title.setGravity(Gravity.CENTER);box.addView(title);TextView number=label(dialogValue+"%",48,INK,false);number.setGravity(Gravity.CENTER);box.addView(number);SeekBar seek=new SeekBar(this);seek.setMax(100);seek.setProgress(dialogValue);seek.setContentDescription("任务进度，0 至 100 百分比");box.addView(seek,new LinearLayout.LayoutParams(-1,dp(this,56)));LinearLayout ends=row();ends.addView(label("0%",14,MUTED,false),new LinearLayout.LayoutParams(0,-2,1));ends.addView(label("100%",14,MUTED,false));box.addView(ends);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){dialogValue=v;number.setText(v+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});AlertDialog dlg=new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("调整任务进度").setView(box).setNegativeButton("取消",null).setPositiveButton("保存进度",null).create();activeDialog=dlg;dlg.setOnShowListener(d->dlg.getButton(-1).setOnClickListener(v->{try{int current=progress(id,store.getDaySnapshot(today));store.setTaskProgress(id,seek.getProgress());DailyArchive.schedule(this);dlg.dismiss();render();if(current>=0&&current<100&&seek.getProgress()==100)celebrate(task.title);}catch(RuntimeException e){toast(e.getMessage());}}));dlg.setOnDismissListener(d->{if(activeDialog==dlg){activeDialog=null;dialogKind=null;}});dlg.show();}
    private void celebrate(String title){UiKit.Fireworks f=new UiKit.Fireworks(this);content.addView(f,new FrameLayout.LayoutParams(-1,-1));toast(title+"已完成");handler.postDelayed(()->{if(f.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)f.getParent()).removeView(f);},2000);}
    private void openEditor(String id){clearDraft();editId=id;LedgerStore.Task t=store.getTask(id);draftName=t==null?"":t.title;draftProgress=t==null?0:progress(id,store.getDaySnapshot(today));draftRank=t==null?store.getTasks(today).size():Math.max(0,t.sort);page="edit";render();}
    private void captureDraft(){if("edit".equals(page)&&editorName!=null){draftName=editorName.getText().toString();draftProgress=editorProgress==null?draftProgress:editorProgress.getProgress();draftRank=editorRank==null?draftRank:editorRank.getSelectedItemPosition();}}
    private void clearDraft(){editId=null;draftName=null;draftRank=-1;editorName=null;editorProgress=null;editorRank=null;reorderIds=null;reordered=false;}
    private void renderEditor(){header(editId==null?"新增任务":"编辑任务",true);gap(body,26);body.addView(label("任务名称",16,INK,true));gap(body,10);editorName=new EditText(this);editorName.setSingleLine(true);editorName.setTextSize(18);editorName.setTextColor(INK);editorName.setFilters(new InputFilter[]{new InputFilter.LengthFilter(30)});editorName.setBackground(shape(0xDEFFFFFF,0xffD7E1DE,10,this));editorName.setPadding(dp(this,14),dp(this,12),dp(this,14),dp(this,12));editorName.setText(draftName);editorName.setHint("输入任务或项目名称");body.addView(editorName,new LinearLayout.LayoutParams(-1,dp(this,58*Math.max(1,getResources().getConfiguration().fontScale/1.3f))));gap(body,8);body.addView(label("任务与项目共用一个列表 · 最多 30 字",12,MUTED,false));gap(body,30);
        if(editId==null){body.addView(label("初始进度",16,INK,true));TextView n=label(draftProgress+"%",24,TEAL,false);body.addView(n);editorProgress=new SeekBar(this);editorProgress.setMax(100);editorProgress.setProgress(draftProgress);body.addView(editorProgress,new LinearLayout.LayoutParams(-1,dp(this,48)));editorProgress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean u){n.setText(p+"%");}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});gap(body,24);}
        body.addView(label("优先级",16,INK,true));gap(body,10);int count=store.getTasks(today).size()+(editId==null?1:0);List<String> ranks=new ArrayList<>();for(int i=0;i<count;i++)ranks.add("第 "+(i+1)+" 位"+(i==count-1?" · 列表末尾":""));editorRank=new Spinner(this);editorRank.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ranks));editorRank.setSelection(Math.min(Math.max(0,draftRank),Math.max(0,count-1)));body.addView(editorRank,new LinearLayout.LayoutParams(-1,dp(this,56)));gap(body,34);body.addView(button("保存任务",true,()->{captureDraft();run(()->{if(editId==null)store.saveSimpleTask(draftName,draftProgress,draftRank+1);else store.updateSimpleTask(editId,draftName,draftRank+1);DailyArchive.schedule(this);page="";clearDraft();render();});}),new LinearLayout.LayoutParams(-1,dp(this,56)));
        if(editId!=null){gap(body,12);body.addView(button("调整进度",false,()->progressDialog(editId,-1)));gap(body,26);TextView remove=label("删除任务",17,RED,false);remove.setGravity(Gravity.CENTER);remove.setPadding(0,dp(this,15),0,dp(this,15));remove.setOnClickListener(v->new AlertDialog.Builder(this,R.style.ShibenDangerDialog).setTitle("删除「"+store.getTask(editId).title+"」？").setMessage("从当前任务列表移除，已有专注记录与历史快照仍保留。今日总进度会按剩余任务重新计算。").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->run(()->{store.archiveTask(editId);DailyArchive.schedule(this);page="";clearDraft();render();})).show());body.addView(remove);}}
    private void leaveEditor(Runnable next){if("edit".equals(page)||("reorder".equals(page)&&reordered))new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("放弃未保存的更改？").setNegativeButton("继续编辑",null).setPositiveButton("放弃",(d,w)->next.run()).show();else next.run();}
    private void renderReorder(){LinearLayout h=header("调整优先级",true);h.addView(textAction("完成",()->run(()->{store.reorderTasks(reorderIds);DailyArchive.schedule(this);page="";clearDraft();render();})));gap(body,20);body.addView(label("长按拖动排序，也可用上下按钮。\n排序会影响今日总进度。",14,MUTED,false));gap(body,18);if(reorderIds==null){reorderIds=new ArrayList<>();for(LedgerStore.Task t:store.getTasks(today))reorderIds.add(t.id);}for(int i=0;i<reorderIds.size();i++){final int index=i;String id=reorderIds.get(i);LedgerStore.Task t=store.getTask(id);if(t==null)continue;LinearLayout row=row();row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(this,12),dp(this,10),dp(this,8),dp(this,10));row.setBackground(shape(0xEFFFFFFF,0x44DDE5E1,16,this));row.addView(label((i+1)+"",16,MUTED,false),new LinearLayout.LayoutParams(dp(this,30),-2));TextView title=label(t.title,18,INK,false);title.setMaxLines(2);title.setPadding(dp(this,8),0,dp(this,4),0);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));row.addView(textAction("↑",()->moveOrder(index,-1)));row.addView(textAction("↓",()->moveOrder(index,1)));Icon handle=new Icon(this,"drag",MUTED);row.addView(handle,new LinearLayout.LayoutParams(dp(this,28),dp(this,36)));row.setOnLongClickListener(v->{v.startDragAndDrop(ClipData.newPlainText("task",id),new View.DragShadowBuilder(v),id,0);return true;});row.setOnDragListener((v,e)->{if(e.getAction()==DragEvent.ACTION_DRAG_STARTED)return e.getLocalState() instanceof String;if(e.getAction()==DragEvent.ACTION_DROP){String from=(String)e.getLocalState();int old=reorderIds.indexOf(from);if(old>=0&&old!=index){reorderIds.remove(old);reorderIds.add(index,from);reordered=true;render();}return true;}return true;});body.addView(row,new LinearLayout.LayoutParams(-1,-2));gap(body,10);}}
    private void moveOrder(int index,int delta){int to=index+delta;if(to<0||to>=reorderIds.size())return;Collections.swap(reorderIds,index,to);reordered=true;render();}

    private View summaryTaskRow(String title,int value){LinearLayout r=row();r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(this,3),dp(this,7),dp(this,3),dp(this,7));r.setMinimumHeight(dp(this,44));r.addView(new UiKit.TaskBadge(this,title),new LinearLayout.LayoutParams(dp(this,28),dp(this,28)));TextView name=label(title,15,INK,false);name.setSingleLine();name.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1.1f);np.setMargins(dp(this,8),0,dp(this,8),0);r.addView(name,np);r.addView(new UiKit.Bar(this,value),new LinearLayout.LayoutParams(0,dp(this,16),1));TextView percent=label(value<0?"未知":value+"%",13,INK,false);percent.setSingleLine();percent.setGravity(Gravity.END);r.addView(percent,new LinearLayout.LayoutParams(dp(this,42*Math.max(1,getResources().getConfiguration().fontScale)),-2));return r;}
