        header("今日进度",false);body.addView(label(today.getMonthValue()+"月"+today.getDayOfMonth()+"日",15,MUTED,false));
        LedgerStore.DaySnapshot day=timer.snapshotForDay(today);UiKit.Ring total=new UiKit.Ring(this);total.set(day.totalProgress/100,V2Reports.totalPercent(day),"今日已完成",false);body.addView(total,new LinearLayout.LayoutParams(-1,dp(this,200)));
