        FrameLayout badge=new FrameLayout(this);badge.setBackground(shape(0xffD9EEE7,0,22,this));badge.addView(new Icon(this,"history",INK),new FrameLayout.LayoutParams(dp(this,26),dp(this,26),Gravity.CENTER));attention.addView(badge,new LinearLayout.LayoutParams(dp(this,42),dp(this,42)));
        LinearLayout words=column();words.setPadding(dp(this,12),0,0,0);words.addView(label("今日投资注意力时长",13,MUTED,false));gap(words,5);attentionTotal=label(attentionDuration(day.totalActualMs),22,INK,true);attentionTotal.setSingleLine();attentionTotal.setAutoSizeTextTypeUniformWithConfiguration(10,22,1,2);words.addView(attentionTotal,new LinearLayout.LayoutParams(-1,dp(this,30)));gap(words,5);attentionBreakdown=label("",11,MUTED,false);words.addView(attentionBreakdown);attention.addView(words,new LinearLayout.LayoutParams(0,-2,1));body.addView(attention);gap(body,12);
        LinearLayout summary=glassPanel();summary.setPadding(dp(this,12),dp(this,8),dp(this,12),dp(this,8));for(LedgerStore.DayTask t:day.items)if(!t.archived){summary.addView(summaryTaskRow(t.title,t.progress));divider(summary);}if(store.getTasks(today).isEmpty()){TextView empty=label("暂无任务，今日总进度为 0%",15,MUTED,false);empty.setGravity(Gravity.CENTER);empty.setPadding(0,dp(this,20),0,dp(this,20));summary.addView(empty,new LinearLayout.LayoutParams(-1,-2));}LinearLayout more=menu("更多","more",()->navigate("more"));more.setBackgroundColor(android.graphics.Color.TRANSPARENT);more.setMinimumHeight(dp(this,48));more.setPadding(dp(this,4),dp(this,8),dp(this,4),dp(this,8));summary.addView(more);body.addView(summary);
