    private void updateManualLabels(){
        LedgerStore.Task selected=null;for(LedgerStore.Task task:store.getManualTasks(manualDate))if(task.id.equals(manualTaskId))selected=task;
        manualTaskLabel.setText(selected==null?"请选择任务":selected.title+(selected.archived?"（已移除）":""));manualDateLabel.setText(manualDate.getYear()+"年"+manualDate.getMonthValue()+"月"+manualDate.getDayOfMonth()+"日");manualTimeLabel.setText(String.format(Locale.ROOT,"%02d:%02d",manualHour,manualMinute));
        for(TextView value:Arrays.asList(manualTaskLabel,manualDateLabel,manualTimeLabel))((View)value.getParent()).setContentDescription(value.getTag()+"，"+value.getText());updateManualHint();
    }
    private void chooseManualTask(){
        if(manualChildDialog!=null&&manualChildDialog.isShowing())return;
        List<LedgerStore.Task> tasks=store.getManualTasks(manualDate);if(tasks.isEmpty()){showManualError("还没有可补记的任务，请先在任务页添加任务");return;}
        String[] labels=new String[tasks.size()];int selected=-1;for(int i=0;i<tasks.size();i++){LedgerStore.Task task=tasks.get(i);labels[i]=task.title+(task.archived?"（已移除）":"");if(task.id.equals(manualTaskId))selected=i;}final int[] pick={selected};AlertDialog choices=new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("选择任务").setSingleChoiceItems(labels,selected,(dialog,which)->pick[0]=which).setNegativeButton("取消",null).setPositiveButton("确定",null).create();choices.setOnShowListener(d->choices.getButton(-1).setOnClickListener(v->{if(pick[0]<0){toast("请选择一个任务");return;}manualTaskId=tasks.get(pick[0]).id;manualDirty=true;clearManualError();updateManualLabels();choices.dismiss();}));manualChildDialog=choices;choices.setOnDismissListener(d->{if(manualChildDialog==choices)manualChildDialog=null;});choices.show();
    }
    private void chooseManualDate(){if(manualChildDialog!=null&&manualChildDialog.isShowing())return;DatePickerDialog picker=new DatePickerDialog(this,(v,y,m,d)->{manualDate=LocalDate.of(y,m+1,d);manualDirty=true;clearManualError();updateManualLabels();},manualDate.getYear(),manualDate.getMonthValue()-1,manualDate.getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());manualChildDialog=picker;picker.setOnDismissListener(d->{if(manualChildDialog==picker)manualChildDialog=null;});picker.show();}
    private void chooseManualTime(){if(manualChildDialog!=null&&manualChildDialog.isShowing())return;TimePickerDialog picker=new TimePickerDialog(this,(v,h,m)->{manualHour=h;manualMinute=m;manualDirty=true;clearManualError();updateManualLabels();},manualHour,manualMinute,true);manualChildDialog=picker;picker.setOnDismissListener(d->{if(manualChildDialog==picker)manualChildDialog=null;});picker.show();}
    private long manualDurationMs(){
        if(manualHours.trim().isEmpty()||manualMinutes.trim().isEmpty())throw new IllegalArgumentException("请填写小时和分钟，不足一小时可填写 0");
        try{long h=Long.parseLong(manualHours),m=Long.parseLong(manualMinutes);if(h<0||m<0||m>59)throw new IllegalArgumentException("分钟请填写 0 至 59");long duration=Math.multiplyExact(Math.addExact(Math.multiplyExact(h,60),m),60000);if(duration<=0)throw new IllegalArgumentException("实际时长至少为 1 分钟");return duration;}catch(NumberFormatException|ArithmeticException invalid){throw new IllegalArgumentException("时长无效，请填写合理的小时和分钟");}
    }
    /** Reject DST gaps; in an overlap choose the first occurrence and disclose the UTC offset. */
    private ZonedDateTime manualStart(){LocalDateTime local=manualDate.atTime(manualHour,manualMinute);ZoneId zone=ZoneId.of(manualZone);List<ZoneOffset> offsets=zone.getRules().getValidOffsets(local);if(offsets.isEmpty())throw new IllegalArgumentException("这个开始时间因夏令时切换不存在，请选择其他时间");ZoneOffset first=offsets.get(0);for(ZoneOffset offset:offsets)if(local.toInstant(offset).isBefore(local.toInstant(first)))first=offset;return ZonedDateTime.ofStrict(local,first,zone);}
    private void updateManualHint(){if(manualHint==null)return;try{ZonedDateTime start=manualStart();String hint="时区 "+manualZone;List<ZoneOffset> offsets=start.getZone().getRules().getValidOffsets(start.toLocalDateTime());if(offsets.size()>1)hint+="\n该时间出现两次，按第一次（UTC"+start.getOffset()+"）补记";try{ZonedDateTime end=start.plus(Duration.ofMillis(manualDurationMs()));hint+="\n结束 "+end.format(DateTimeFormatter.ofPattern("yyyy年M月d日 HH:mm"));}catch(RuntimeException invalid){/* Inline validation is shown only when saving. */}manualHint.setText(hint);}catch(RuntimeException invalid){manualHint.setText(invalid.getMessage());}}
    private void saveManualDraft(Bundle d){if(manualHoursInput!=null)manualHours=manualHoursInput.getText().toString();if(manualMinutesInput!=null)manualMinutes=manualMinutesInput.getText().toString();d.putString("manualTaskId",manualTaskId);d.putString("manualDate",manualDate.toString());d.putInt("manualHour",manualHour);d.putInt("manualMinute",manualMinute);d.putString("manualZone",manualZone);d.putString("manualHours",manualHours);d.putString("manualMinutes",manualMinutes);d.putString("manualSessionId",manualSessionId);d.putBoolean("manualDirty",manualDirty);}
    private void clearManualError(){if(manualError!=null){manualError.setText("");manualError.setVisibility(View.GONE);}}
    private void showManualError(String text){if(manualError==null){toast(text);return;}manualError.setText(text);manualError.setPadding(0,dp(this,12),0,0);manualError.setVisibility(View.VISIBLE);manualError.post(()->{if(manualError!=null)manualError.requestRectangleOnScreen(new android.graphics.Rect(0,0,manualError.getWidth(),manualError.getHeight()));});}
    private void cancelManual(AlertDialog dlg){if(manualSaving||manualCancelPrompt)return;if(!manualDirty){dlg.dismiss();return;}manualCancelPrompt=true;AlertDialog confirm=new AlertDialog.Builder(this,R.style.ShibenDialog).setTitle("放弃这次补记？").setMessage("已填写的内容尚未保存。").setNegativeButton("继续填写",null).setPositiveButton("放弃",(d,w)->dlg.dismiss()).create();manualChildDialog=confirm;confirm.setOnDismissListener(d->{manualCancelPrompt=false;if(manualChildDialog==confirm)manualChildDialog=null;});confirm.show();}
    private void saveManualSession(AlertDialog dlg){
        if(manualSaving)return;manualSaving=true;dlg.getButton(-1).setEnabled(false);clearManualError();boolean saved=false;
        try{
            manualHours=manualHoursInput.getText().toString();manualMinutes=manualMinutesInput.getText().toString();if(timer.engine().isActive())throw new IllegalArgumentException("请先结束当前计时，再补记注意力时长");
            LedgerStore.Task task=null;for(LedgerStore.Task candidate:store.getManualTasks(manualDate))if(candidate.id.equals(manualTaskId))task=candidate;if(task==null)throw new IllegalArgumentException("请选择这一天可补记的任务");
            long duration=manualDurationMs();ZonedDateTime start=manualStart();Session session=Session.manual(manualSessionId,task.id,task.title,task.projectId,start.toInstant().toEpochMilli(),duration,manualZone,false);if(session.startedWallMs>System.currentTimeMillis()||session.endedWallMs>System.currentTimeMillis())throw new IllegalArgumentException("只能补记已发生的时间，结束时间不能晚于现在");
            Session existing=store.getSession(manualSessionId);if(existing==null)store.addManualSession(session);else if(!existing.manual||!existing.taskId.equals(session.taskId)||existing.startedWallMs!=session.startedWallMs||existing.actualMs!=session.actualMs)throw new IllegalArgumentException("这次补记已保存，请重新打开后填写新记录");
            saved=true;manualDirty=false;DailyArchive.schedule(this);dlg.dismiss();render();toast("注意力时长已补记");
        }catch(RuntimeException invalid){showManualError(invalid.getMessage()==null?"补记未保存，请重试":invalid.getMessage());}finally{if(!saved){manualSaving=false;dlg.getButton(-1).setEnabled(true);}}
    }
